   const r=sim.racers[0],p=racerPose(r,alpha),f=new THREE.Vector3(Math.sin(p.yaw),0,Math.cos(p.yaw)),desired=new THREE.Vector3(p.x,p.y+(this.water?4.8:5.8),p.z).addScaledVector(f,-(this.water?15:18));desired.y=Math.max(sim.groundAt(desired.x,desired.z)+3,desired.y);const look=new THREE.Vector3(p.x,p.y+.7,p.z).addScaledVector(f,12);const blend=this.cameraReady?1-Math.exp(-dt*6):1;this.camera.position.lerp(desired,blend);this.target.lerp(look,blend);this.camera.lookAt(this.target);this.cameraReady=true;this.camera.fov+=(r.boosting?70-this.camera.fov:64-this.camera.fov)*dt*3;this.camera.updateProjectionMatrix();this.scene.fog.density=this.water?(h.theme==='blackwater'?.012:.006):.0025;this.shellMaterials.forEach(m=>m.opacity=.04);
